    try { expected_port = $('Hub Proxy 4').first(0, $runIndex).json.proxy.porta; } catch(e) {}
    try { actual_port = $('Set Proxy (4)').first(0, $runIndex).json.proxy.proxy.port; } catch(e) {}
} else if (executed_tentativa5) {
    try { expected_port = $('Hub Proxy 5').first(0, $runIndex).json.proxy.porta; } catch(e) {}
    try { actual_port = $('Set Proxy (5)').first(0, $runIndex).json.proxy.proxy.port; } catch(e) {}
