let items = $input.all();

// Se houver mais de 5 mensagens reservadas no lote atual, embaralha a ordem de envio
if (items.length > 5) {
    // Algoritmo de Fisher-Yates para garantir um embaralhamento perfeito e aleatório
    for (let i = items.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        // Troca os itens de lugar
        [items[i], items[j]] = [items[j], items[i]];
    }
}

return items;

